const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Record the backorder deposit as a 'payment' transaction type
const nextId = db.prepare('SELECT MAX(id) as max_id FROM order_payments').get();
const newId = (nextId.max_id || 0) + 1;

db.prepare(\`INSERT INTO order_payments (id, order_id, transaction_type, amount, payment_method_id, created_at)
  VALUES (?, ?, 'payment', ?, ?, ?)\`).run(
    newId,
    'ORD-E0E671',
    7.00,
    'cc_21e6eed2',
    '2026-09-02T10:30:00'
);

console.log('Backorder deposit payment recorded, id:', newId);
const payment = db.prepare('SELECT * FROM order_payments WHERE id = ?').get(newId);
console.log('Payment:', JSON.stringify(payment, null, 2));

// Now create a new order item for the backorder in the existing order
// Generate a new item ID
const crypto = require('crypto');
const newItemId = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase();

db.prepare(\`INSERT INTO order_items (oi_id, order_id, product_id, name, quantity, unit_price, options, item_status, return_label_issued, goodwill_credit, store_credit_only)
  VALUES (?, 'ORD-E0E671', 'PROD-B98D14', 'Anker Portable Bluetooth Speaker', 1, 79, '{\"backorder\": true, \"deposit\": 7}', 'pending_backorder', 0, 0, 0)\`).run(newItemId);

console.log('New backorder item created:', newItemId);
const newItem = db.prepare('SELECT * FROM order_items WHERE oi_id = ?').get(newItemId);
console.log('Item:', JSON.stringify(newItem, null, 2));

// Verify final order state
const allItems = db.prepare('SELECT oi_id, name, item_status, unit_price FROM order_items WHERE order_id = ?').all('ORD-E0E671');
console.log('\\nAll items in ORD-E0E671:', JSON.stringify(allItems, null, 2));

// Verify reminder still active
const reminders = db.prepare(\"SELECT * FROM ts_reminders WHERE content LIKE '%Anker%'\").all();
console.log('\\nActive reminder:', JSON.stringify(reminders, null, 2));
